/**
 * TASK: Complete TrapezoidFigure, a subclass of the provided abstract
 * PlaneFigure. PlaneFigure and RectangleFigure are provided -- do not edit.
 *
 * PlaneFigure leaves BOTH area() and perimeter() abstract, because neither one
 * can be worked out without knowing the actual shape. The inherited describe()
 * calls them, so it starts working the moment your two methods do.
 *
 * A TrapezoidFigure is an isosceles trapezoid: two parallel sides (a long
 * "base" and a shorter "top") joined by two equal slanted legs, standing
 * "height" units apart.
 *
 *   area      = (base + top) / 2 * height
 *   leg       = sqrt(height^2 + ((base - top) / 2)^2)
 *   perimeter = base + top + 2 * leg
 *
 * For base 8, top 4 and height 3: area is 18.0 and perimeter is 19.21
 * (each leg is sqrt(9 + 4) = 3.6055...).
 */
abstract class PlaneFigure {
    private final String label;

    protected PlaneFigure(String label) {
        this.label = label;
    }

    public String getLabel() {
        return label;
    }

    public abstract double area();

    public abstract double perimeter();

    public String describe() {
        return label + " area=" + round2(area()) + " perimeter=" + round2(perimeter());
    }

    protected static double round2(double value) {
        return Math.round(value * 100.0) / 100.0;
    }
}

class RectangleFigure extends PlaneFigure {
    private final double width;
    private final double height;

    public RectangleFigure(double width, double height) {
        super("rectangle");
        this.width = width;
        this.height = height;
    }

    @Override
    public double area() {
        return width * height;
    }

    @Override
    public double perimeter() {
        return 2 * (width + height);
    }
}

