public class TrapezoidFigureTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static Object safe(java.util.function.Supplier<Object> body) {
        try {
            return body.get();
        } catch (Throwable t) {
            return "<threw " + t.getClass().getSimpleName() + ">";
        }
    }

    static Object round2(java.util.function.Supplier<Double> body) {
        try {
            return Math.round(body.get() * 100.0) / 100.0;
        } catch (Throwable t) {
            return "<threw " + t.getClass().getSimpleName() + ">";
        }
    }

    public static void main(String[] args) {
        TrapezoidFigure trapezoid = new TrapezoidFigure(8, 4, 3);

        check("area", 18.0, round2(trapezoid::area));
        check("perimeter", 19.21, round2(trapezoid::perimeter));
        check("label was passed up to the superclass", "trapezoid", safe(trapezoid::getLabel));
        check("inherited describe uses both overrides",
                "trapezoid area=18.0 perimeter=19.21", safe(trapezoid::describe));

        TrapezoidFigure square = new TrapezoidFigure(5, 5, 5);
        check("equal parallel sides give a square area", 25.0, round2(square::area));
        check("equal parallel sides give a square perimeter", 20.0, round2(square::perimeter));

        TrapezoidFigure spike = new TrapezoidFigure(6, 0, 4);
        check("a zero top is a triangle area", 12.0, round2(spike::area));
        check("a zero top is a triangle perimeter", 16.0, round2(spike::perimeter));

        PlaneFigure[] figures = {new RectangleFigure(2, 3), new TrapezoidFigure(8, 4, 3)};
        check("polymorphic total area", 24.0,
                round2(() -> figures[0].area() + figures[1].area()));

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

