    protected PlaneFigure(String label) {
        this.label = label;
    }

    public String getLabel() {
        return label;
    }

    public abstract double area();

    public abstract double perimeter();

    public String describe() {
        return label + " area=" + round2(area()) + " perimeter=" + round2(perimeter());
    }

    protected static double round2(double value) {
        return Math.round(value * 100.0) / 100.0;
    }
}

class RectangleFigure extends PlaneFigure {
    private final double width;
    private final double height;

    public RectangleFigure(double width, double height) {
        super("rectangle");
        this.width = width;
        this.height = height;
    }

    @Override
    public double area() {
        return width * height;
    }

    @Override
    public double perimeter() {
        return 2 * (width + height);
    }
