public class TrapezoidFigure extends PlaneFigure {

    private final double base;
    private final double top;
    private final double height;

    public TrapezoidFigure(double base, double top, double height) {
        super("trapezoid");
        this.base = base;
        this.top = top;
        this.height = height;
    }

    @Override
    public double area() {
        return (base + top) / 2 * height;
    }

    @Override
    public double perimeter() {
        double halfDifference = (base - top) / 2;
        double leg = Math.sqrt(height * height + halfDifference * halfDifference);
        return base + top + 2 * leg;
    }
}
